105	    /// Find YAML files in `.bivvy/<subdir>/`.
106	    ///
107	    /// Returns sorted paths for deterministic merge order.
108	    fn find_split_files(project_root: &Path, subdir: &str) -> Vec<PathBuf> {
109	        let dir = project_root.join(".bivvy").join(subdir);
110	        if !dir.is_dir() {
111	            return Vec::new();
112	        }
113	
114	        let mut files: Vec<PathBuf> = fs::read_dir(&dir)
115	            .into_iter()
116	            .flatten()
117	            .filter_map(|entry| entry.ok())
118	            .map(|entry| entry.path())
119	            .filter(|path| {
120	                path.extension()
121	                    .is_some_and(|ext| ext == "yml" || ext == "yaml")
122	            })
123	            .collect();
124	
125	        files.sort();
126	        files
127	    }
128	
129	    /// Returns all existing config paths in merge order (excludes split files).
130	    pub fn all_existing(&self) -> Vec<&PathBuf> {
131	        let mut paths = Vec::new();
132	
133	        for p in &self.extends {
134	            paths.push(p);
135	        }
136	
137	        if let Some(p) = &self.user_global {
138	            paths.push(p);
139	        }
140	
141	        if let Some(p) = &self.project {
142	            paths.push(p);
143	        }
144	
145	        if let Some(p) = &self.project_local {
146	            paths.push(p);
147	        }
148	
149	        paths
150	    }
151	
152	    /// Check if any project config exists.
153	    ///
154	    /// Returns true if `.bivvy/config.yml` exists OR if any split-file
155	    /// steps/workflows are present.
156	    pub fn has_project_config(&self) -> bool {
157	        self.project.is_some() || !self.split_steps.is_empty() || !self.split_workflows.is_empty()
158	    }
159	
160	    /// Whether any split files were discovered.
161	    pub fn has_split_files(&self) -> bool {
162	        !self.split_steps.is_empty() || !self.split_workflows.is_empty()
163	    }
164	}
